function OverManegeLoungeFeedNode:FreshUI(data,  responseRegions)
    local goodsId  = data.goodsId
    local goodsNum = data.goodsNum
    
    ---@type GoodsVo
    local goodsVo = goodsConfMgr:GetGoodsVoById(goodsId)
    self.ImgIcon:LoadSprite(goodsVo.photoPath)
    
    self.TextNumber.text  = goodsNum
    self._goodsId        = goodsId
    self._goodsNum        = goodsNum
    self._responseRegions = responseRegions 
end

