--region handler

function OverManegeLoungeFeedNode:OnPointerBeginDrag(eventData)
    if self._goodsNum <= 0 then return end
    
    self._originPosition = self._imgIconTrans.anchoredPosition
    
end

local RectTransformUtility = CS.UnityEngine.RectTransformUtility
function OverManegeLoungeFeedNode:OnPointerDrag(eventData)
    if self._goodsNum <= 0 then return end

    local bool, vecNow = RectTransformUtility.ScreenPointToWorldPointInRectangle(self._draggingPlane, eventData.position, eventData.pressEventCamera, Vector3.New(0, 0, 0))
    self._imgIconTrans.position = vecNow
   
end

function OverManegeLoungeFeedNode:OnPointerEndDrag(eventData)
    if self._goodsNum <= 0 then return end
    
    if self._responseRegions then
        for i, trans in ipairs(self._responseRegions) do
            local isHit = trans:Overlaps(self._imgIconTrans)
            if isHit then
                Events.Broadcast(MaidCoffeeConstants.EventNames.LoungeHitCat, i, self._goodsId)
                break
            end
        end
    end
    self._imgIconTrans.anchoredPosition = self._originPosition
end


--region handler

return OverManegeLoungeFeedNode